namespace App\Elephentity\Pattern\Auditable;

use DateTimeImmutable;

/**
 * The Auditable fields and edges, for code that only needs those and not the whole entity.
 *
 * Every entity using Auditable already has these getters — this names the shape, it does
 * not add anything an application has to implement.
 */
interface Auditable
{
    public function getCreatedAt(): DateTimeImmutable;

    public function getUpdatedAt(): DateTimeImmutable;
}

namespace App\Elephentity\Pattern\Auditable;

/**
 * Auditable's own setters, mixed into every entity mutator that applies it.
 *
 * Assumes the using class has a private MutationBuffer $buffer — true of every
 * generated {Entity}Mutator, and the only thing this trait requires of it.
 */
trait AuditableMutatorTrait
{
}

